$$
\begin{aligned}
a_{n} & =\sin ^{2} \pi \sqrt{n^{2}+n}=\sin ^{2} \pi\left(\sqrt{n^{2}+n}-n+n\right) \\
& =\sin ^{2} \pi\left(\frac{\left(\sqrt{n^{2}+n}-n\right)\left(\sqrt{n^{2}+n}+n\right)}{\sqrt{n^{2}+n}+n}+n\right)=\sin ^{2} \pi\left(\frac{n^{2}+n-n^{2}}{\sqrt{n^{2}+n}+n}+n\right) \\
